UPDATE USER_KPI_SUMMARIES
SET
    EVALUATION_SUPERVISOR_COMMENTS = #{comments},
    EVALUATOR_ID = #{evaluatorId, jdbcType=OTHER},
    UPDATED_AT = CURRENT_TIMESTAMP,
    UPDATED_BY = #{updatedBy, jdbcType=OTHER}
WHERE USER_ID = #{userId, jdbcType=OTHER}
  AND CYCLE_ID = #{cycleId, jdbcType=OTHER}
  AND DELETED_AT IS NULL
